      '        <div class="hg-toggle-item" id="hg-toggle-autotarget" style="padding:2px 6px; gap:6px;">',
      '          <span style="font-size:10px; color:#cbd5e1;">启用巡航</span>',
      '          <div class="hg-switch" style="width:28px; height:16px;"></div>',
      '        </div>',
      '      </div>',
      '      <!-- 目标阵容多选 -->',
      '      <div style="display:flex; justify-content:space-between; align-items:center;">',
      '        <span style="font-size:11px; color:#cbd5e1;">目标阵容筛选:</span>',
