      '        <span class="hg-chip" data-label="三蜀">三蜀</span>',
      '        <span class="hg-chip" data-label="合力">合力</span>',
      '        <span class="hg-chip" data-label="吴国">吴国</span>',
      '        <span class="hg-chip" data-label="毒爆">毒爆</span>',
      '        <span class="hg-chip" data-label="关羽">关羽</span>',
