      '        <span id="hg-sort-mode-desc" style="font-size:10px; color:#fbbf24;">战力降序</span>',
      '      </div>',
      '      <div class="hg-sort-row">',
      '        <button class="hg-sort-btn" id="hg-sort-power">战力</button>',
      '        <button class="hg-sort-btn" id="hg-sort-energy">精力</button>',
      '        <button class="hg-sort-btn" id="hg-sort-march">到达</button>',
      '        <button class="hg-sort-btn" id="hg-sort-restore">还原</button>',
      '      </div>',
      '    </div>',
      '    <!-- 锁头作战监控与队列 -->',
